using System.ComponentModel.DataAnnotations;

namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }

    [Required, StringLength(100)]
    public string Title { get; set; } = string.Empty;

    [Required]
    public string Category { get; set; } = string.Empty;

    [Required]
    public string Ingredients { get; set; } = string.Empty;

    [Required]
    public string Steps { get; set; } = string.Empty;

    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public static class RecipeStore
{
    private static readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
            Steps = "1. Preheat oven to 475°F\n2. Roll out dough into a circle\n3. Spread crushed tomatoes evenly\n4. Tear mozzarella and distribute\n5. Bake 10-12 minutes\n6. Top with fresh basil and drizzle olive oil",
            AverageRating = 4.5, RatingCount = 12
        },
        new Recipe
        {
            Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nTomato sauce\nHeavy cream\nGarlic\nGinger",
            Steps = "1. Marinate chicken in yogurt and spices for 2 hours\n2. Grill or pan-fry chicken until charred\n3. Sauté garlic and ginger\n4. Add tomato sauce and spices\n5. Simmer 15 minutes\n6. Add cream and cooked chicken\n7. Serve with basmati rice",
            AverageRating = 4.8, RatingCount = 24
        },
        new Recipe
        {
            Id = 3, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa",
            Steps = "1. Brown ground beef in a skillet\n2. Add taco seasoning and water\n3. Simmer until thickened\n4. Warm tortillas\n5. Assemble tacos with toppings",
            AverageRating = 4.2, RatingCount = 8
        },
        new Recipe
        {
            Id = 4, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti\nGuanciale\nEgg yolks\nPecorino Romano\nBlack pepper",
            Steps = "1. Cook pasta in salted water\n2. Crisp guanciale in a pan\n3. Whisk egg yolks with grated pecorino\n4. Toss hot pasta with guanciale\n5. Remove from heat, add egg mixture\n6. Toss quickly, season with pepper",
            AverageRating = 4.7, RatingCount = 18
        },
        new Recipe
        {
            Id = 5, Title = "Pad Thai", Category = "Thai",
            Ingredients = "Rice noodles\nShrimp\nEgg\nBean sprouts\nGreen onions\nPeanuts\nTamarind paste\nFish sauce\nSugar\nLime",
            Steps = "1. Soak rice noodles in warm water\n2. Make sauce: tamarind, fish sauce, sugar\n3. Stir-fry shrimp, set aside\n4. Scramble egg in wok\n5. Add noodles and sauce\n6. Toss with shrimp, sprouts, onions\n7. Serve with peanuts and lime",
            AverageRating = 4.4, RatingCount = 15
        },
        new Recipe
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt",
            Steps = "1. Halve and pit avocados\n2. Mash to desired consistency\n3. Mix in lime juice and salt\n4. Fold in diced onion, tomato, jalapeño\n5. Top with cilantro\n6. Serve immediately with chips",
            AverageRating = 4.6, RatingCount = 20
        },
        new Recipe
        {
            Id = 7, Title = "Green Curry", Category = "Thai",
            Ingredients = "Coconut milk\nGreen curry paste\nChicken thigh\nBamboo shoots\nThai basil\nFish sauce\nPalm sugar\nEggplant",
            Steps = "1. Heat coconut cream until oil separates\n2. Fry curry paste until fragrant\n3. Add chicken, cook through\n4. Pour in remaining coconut milk\n5. Add vegetables and seasoning\n6. Simmer 10 minutes\n7. Finish with Thai basil",
            AverageRating = 4.3, RatingCount = 11
        },
        new Recipe
        {
            Id = 8, Title = "Butter Chicken", Category = "Indian",
            Ingredients = "Chicken thigh\nYogurt\nButter\nTomato puree\nCream\nGaram masala\nKasuri methi\nGarlic\nGinger",
            Steps = "1. Marinate chicken in yogurt and spices\n2. Grill or bake chicken pieces\n3. Melt butter, sauté garlic and ginger\n4. Add tomato puree, simmer 20 min\n5. Blend sauce until smooth\n6. Add cream and kasuri methi\n7. Add chicken, simmer 5 min",
            AverageRating = 4.9, RatingCount = 30
        }
    };

    public static IReadOnlyList<Recipe> All => _recipes;

    public static IEnumerable<string> Categories =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c);

    public static IEnumerable<Recipe> ByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase));

    public static Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public static void Add(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }

    public static void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is null) return;

        var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
        recipe.RatingCount++;
        recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
    }
}

