arguments.file_text:
@page "/recipes"
@page "/recipes/{Category}"

@using RecipeHub.Models

<PageTitle>@(Category ?? "All Recipes") - RecipeHub</PageTitle>

<h1>@(Category ?? "All") Recipes</h1>

@if (Category is null)
{
    <p>Select a category to browse recipes:</p>
    <ul>
        @foreach (var cat in RecipeStore.Categories)
        {
            <li><a href="recipes/@cat.ToLower()">@cat</a></li>
        }
    </ul>
}
else
{
    var recipes = RecipeStore.ByCategory(Category).ToList();
    if (recipes.Count == 0)
    {
        <p>No recipes found in this category.</p>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in recipes)
            {
                <div class="col-md-6 mb-4">
                    <div class="card h-100">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="card-text">
                                <span class="text-warning">@(new string('★', (int)Math.Round(recipe.AverageRating)))@(new string('☆', 5 - (int)Math.Round(recipe.AverageRating)))</span>
                                <small class="text-muted">(@recipe.AverageRating / 5, @recipe.RatingCount ratings)</small>
                            </p>
                            <a href="recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
}

<a href="/" class="btn btn-secondary mt-3">← Back to Home</a>

@code {
    [Parameter]
    public string? Category { get; set; }
}

@page "/recipe/{Id:int}"

@using RecipeHub.Models

<PageTitle>@(recipe?.Title ?? "Recipe Not Found") - RecipeHub</PageTitle>

@if (recipe is null)
{
    <h1>Recipe Not Found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
}
else
{
    <h1>@recipe.Title</h1>
    <p><span class="badge bg-secondary">@recipe.Category</span></p>

    <div class="row">
        <div class="col-md-8">
            <h3>Ingredients</h3>
            <ul>
                @foreach (var ingredient in recipe.Ingredients.Split('\n'))
                {
                    <li>@ingredient</li>
                }
            </ul>

            <h3>Steps</h3>
            @foreach (var step in recipe.Steps.Split('\n'))
            {
                <p>@step</p>
            }
        </div>
        <div class="col-md-4">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Rate this Recipe</h5>
                    <p class="text-muted">
                        Average: @recipe.AverageRating / 5 (@recipe.RatingCount ratings)
                    </p>
                    <StarRating RecipeId="@recipe.Id" />
                </div>
            </div>
        </div>
    </div>

    <a href="recipes/@recipe.Category.ToLower()" class="btn btn-secondary mt-3">← Back to @recipe.Category Recipes</a>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Recipe? recipe;

    protected override void OnInitialized()
    {
        recipe = RecipeStore.GetById(Id);
    }
}

@rendermode InteractiveServer

@using RecipeHub.Models

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= (hoveredStar ?? selectedStar) ? "filled" : "")"
              @onclick="() => SubmitRating(star)"
              @onmouseover="() => hoveredStar = star"
              @onmouseout="() => hoveredStar = null"
              role="button"
              title="@star star(s)">
            @(star <= (hoveredStar ?? selectedStar) ? "★" : "☆")
        </span>
    }
</div>

@if (submitted)
{
    <p class="text-success mt-2"><small>Thanks for rating!</small></p>
}

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int selectedStar;
    private int? hoveredStar;
    private bool submitted;

    private void SubmitRating(int stars)
    {
        selectedStar = stars;
        RecipeStore.AddRating(RecipeId, stars);
        submitted = true;
    }
}

.star-rating {
    font-size: 2rem;
    cursor: pointer;
}

.star {
    color: #ccc;
    transition: color 0.15s;
}

.star.filled {
    color: #ffc107;
}

.star:hover {
    transform: scale(1.2);
    display: inline-block;
}

@page "/submit"
@rendermode InteractiveServer

@using RecipeHub.Models
@using System.ComponentModel.DataAnnotations

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community.</p>

@if (successMessage is not null)
{
    <div class="alert alert-success">@successMessage</div>
}

<EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" class="form-control" @bind-Value="model.Title" placeholder="e.g., Grandma's Apple Pie" />
        <ValidationMessage For="() => model.Title" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="model.Category">
            <option value="">-- Select a category --</option>
            <option value="Italian">Italian</option>
            <option value="Indian">Indian</option>
            <option value="Mexican">Mexican</option>
            <option value="Thai">Thai</option>
            <option value="American">American</option>
            <option value="French">French</option>
            <option value="Japanese">Japanese</option>
            <option value="Other">Other</option>
        </InputSelect>
        <ValidationMessage For="() => model.Category" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients</label>
        <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="model.Ingredients"
                       placeholder="One ingredient per line" />
        <ValidationMessage For="() => model.Ingredients" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps</label>
        <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="model.Steps"
                       placeholder="Describe each step" />
        <ValidationMessage For="() => model.Steps" class="text-danger" />
    </div>

    <button type="submit" class="btn btn-primary">Submit Recipe</button>
</EditForm>

@code {
    private RecipeFormModel model = new();
    private string? successMessage;

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = model.Title,
            Category = model.Category,
            Ingredients = model.Ingredients,
            Steps = model.Steps
        };

        RecipeStore.Add(recipe);
        successMessage = $"'{model.Title}' has been submitted successfully!";
        model = new();
    }

    private class RecipeFormModel
    {
        [Required(ErrorMessage = "Please enter a recipe title.")]
        [StringLength(100, ErrorMessage = "Title must be 100 characters or fewer.")]
        public string Title { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please list the ingredients.")]
        public string Ingredients { get; set; } = string.Empty;

        [Required(ErrorMessage = "Please describe the steps.")]
        public string Steps { get; set; } = string.Empty;
    }
}

